import { test, expect } from '../../../fixtures';

test('TC-029: Verify role permissions remain enforced after re-authentication (regression)', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('standard_user');
  const res = await api.get('/api/users');
  expect(res.status()).toBe(403);
  // Expected (full): 403 forbidden
  await api.post('/api/auth/logout');
  await loginAs('admin');
  const res2 = await api.get('/api/users');
  expect(res2.status()).toBe(200);
  // Expected (full): 200 allowed
  await api.post('/api/auth/logout');
  await loginAs('standard_user');
  const res3 = await api.get('/api/users');
  expect(res3.status()).toBe(403);
  // Expected (full): 403 forbidden, no privilege leakage
});
